/**
 * Create Event Page (Admin)
 */

import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import eventService from '../services/eventService';
import './CreateEvent.css';

const CreateEvent = () => {
  const navigate = useNavigate();
  const [formData, setFormData] = useState({
    title: '',
    description: '',
    date: '',
    time: '',
    location: '',
    price: '',
    totalSeats: '',
    category: 'Other',
  });
  const [imageFile, setImageFile] = useState(null);
  const [imagePreview, setImagePreview] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const categories = ['Conference', 'Concert', 'Workshop', 'Sports', 'Social', 'Other'];

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({
      ...prev,
      [name]: value,
    }));
  };

  const handleImageSelect = (e) => {
    const file = e.target.files?.[0];
    if (!file) return;

    // Validate file type
    if (!file.type.startsWith('image/')) {
      setError('❌ Please select a valid image file (PNG, JPG)');
      return;
    }

    // Validate file size (2MB)
    if (file.size > 2 * 1024 * 1024) {
      setError('❌ Image size must be less than 2MB');
      return;
    }

    setImageFile(file);
    const reader = new FileReader();
    reader.onloadend = () => {
      setImagePreview(reader.result);
    };
    reader.readAsDataURL(file);
    setError('');
  };

  const handleRemoveImage = () => {
    setImageFile(null);
    setImagePreview(null);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setLoading(true);

    // Client-side validation first
    if (!formData.title?.trim()) {
      setError('❌ Event title is required');
      setLoading(false);
      return;
    }

    if (!formData.description?.trim()) {
      setError('❌ Description is required');
      setLoading(false);
      return;
    }

    if (!formData.date) {
      setError('❌ Event date is required');
      setLoading(false);
      return;
    }

    if (!formData.time) {
      setError('❌ Event time is required');
      setLoading(false);
      return;
    }

    if (!formData.location?.trim()) {
      setError('❌ Location is required');
      setLoading(false);
      return;
    }

    // Validate price
    const price = parseFloat(formData.price);
    if (isNaN(price) || price < 0) {
      setError('❌ Ticket price must be a valid number');
      setLoading(false);
      return;
    }

    // Validate total seats
    const totalSeats = parseInt(formData.totalSeats, 10);
    if (isNaN(totalSeats) || totalSeats < 1) {
      setError('❌ Total seats must be at least 1');
      setLoading(false);
      return;
    }

    if (!imageFile) {
      setError('❌ Please select an event image');
      setLoading(false);
      return;
    }

    // Check if date is in future
    const eventDate = new Date(formData.date);
    eventDate.setHours(0, 0, 0, 0);
    const today = new Date();
    today.setHours(0, 0, 0, 0);

    if (eventDate <= today) {
      setError('❌ Event date must be in the future');
      setLoading(false);
      return;
    }

    // All validations passed, try to create event
    try {
      const formDataToSend = new FormData();
      formDataToSend.append('title', formData.title.trim());
      formDataToSend.append('description', formData.description.trim());
      formDataToSend.append('date', formData.date);
      formDataToSend.append('time', formData.time);
      formDataToSend.append('location', formData.location.trim());
      formDataToSend.append('price', price);
      formDataToSend.append('totalSeats', totalSeats);
      formDataToSend.append('category', formData.category);
      formDataToSend.append('image', imageFile);

      await eventService.createEvent(formDataToSend);
      setError('');
      navigate('/admin/dashboard');
    } catch (err) {
      console.error('Event creation error:', err);
      
      let errorMsg = 'Failed to create event';
      
      // Try to extract error message from various sources
      if (typeof err === 'string') {
        errorMsg = err;
      } else if (err?.response?.data?.message) {
        errorMsg = err.response.data.message;
      } else if (err?.message) {
        errorMsg = err.message;
      } else if (err?.error) {
        errorMsg = err.error;
      } else if (err?.msg) {
        errorMsg = err.msg;
      } else if (typeof err === 'object' && err !== null) {
        errorMsg = JSON.stringify(err);
      }
      
      setError('❌ ' + errorMsg);
      console.error('Event creation error details:', err);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="create-event-page">
      <div className="form-container">
        <h1>🎉 Create New Event</h1>
        <p>Fill in the details below to create a new event for your platform</p>

        {error && <div className="error-message">{error}</div>}

        <form onSubmit={handleSubmit} className="event-form">
          <div className="form-group">
            <label>Event Title *</label>
            <input
              type="text"
              name="title"
              value={formData.title}
              onChange={handleChange}
              placeholder="Enter event title"
              required
            />
          </div>

          <div className="form-group">
            <label>Description *</label>
            <textarea
              name="description"
              value={formData.description}
              onChange={handleChange}
              placeholder="Enter event description"
              rows="4"
              required
            ></textarea>
          </div>

          <div className="form-row">
            <div className="form-group">
              <label>Date *</label>
              <input
                type="date"
                name="date"
                value={formData.date}
                onChange={handleChange}
                required
              />
            </div>

            <div className="form-group">
              <label>Time *</label>
              <input
                type="time"
                name="time"
                value={formData.time}
                onChange={handleChange}
                required
              />
            </div>
          </div>

          <div className="form-group">
            <label>Location *</label>
            <input
              type="text"
              name="location"
              value={formData.location}
              onChange={handleChange}
              placeholder="Enter event location"
              required
            />
          </div>

          <div className="form-row">
            <div className="form-group">
              <label>Ticket Price (₹) *</label>
              <input
                type="number"
                name="price"
                value={formData.price}
                onChange={handleChange}
                placeholder="0"
                min="0"
                step="10"
                required
              />
            </div>

            <div className="form-group">
              <label>Total Seats *</label>
              <input
                type="number"
                name="totalSeats"
                value={formData.totalSeats}
                onChange={handleChange}
                placeholder="0"
                min="1"
                required
              />
            </div>
          </div>

          <div className="form-group">
            <label>Category</label>
            <select
              name="category"
              value={formData.category}
              onChange={handleChange}
            >
              {categories.map((cat) => (
                <option key={cat} value={cat}>
                  {cat}
                </option>
              ))}
            </select>
          </div>

          <div className="form-group">
            <label>Event Image *</label>
            <div className="image-upload-box">
              {imagePreview ? (
                <div className="image-preview-container">
                  <img src={imagePreview} alt="Preview" className="image-preview" />
                  <button
                    type="button"
                    className="remove-image-btn"
                    onClick={handleRemoveImage}
                  >
                    ✕ Remove
                  </button>
                </div>
              ) : (
                <label className="upload-label">
                  <input
                    type="file"
                    accept="image/*"
                    onChange={handleImageSelect}
                    style={{ display: 'none' }}
                  />
                  <div className="upload-content">
                    <div className="upload-icon">📸</div>
                    <p className="upload-text">Click to upload or drag and drop</p>
                    <p className="upload-subtext">PNG, JPG up to 2MB</p>
                  </div>
                </label>
              )}
            </div>
          </div>

          <div className="form-actions">
            <button type="submit" className="btn-submit" disabled={loading}>
              {loading ? 'Creating Event...' : 'Create Event'}
            </button>
            <button
              type="button"
              className="btn-cancel"
              onClick={() => navigate('/admin/dashboard')}
            >
              Cancel
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default CreateEvent;
